        return num % 9 == 0 or num % 12 == 0

    def sum_of_digits(num: int) -> int:
        return sum(int(digit) for digit in str(num))

    def sum_is_multiply_of_three(num: int) -> bool:
        return sum_of_digits(num) % 3 == 0

